/* =========================================================
   包茎手術 3院比較テーブル（.hcmp）
   デザイン刷新版：ボルドー × ゴールド（プレミアム）
   ※HTML・クラス名は変更なし／スマホは縦1画面に収まるコンパクト設計（横スクロール維持）
   ========================================================= */
.hcmp{
  --main:#8E292C;
  --deep:#5E171A;
  --deeper:#431012;
  --gold:#C9A14A;
  --gold-lt:#F4E4B8;
  --gold-hl:#F7E3A6;
  --cta1:#F8CF55;
  --cta2:#E3A21A;
  --cta-sh:#A9770E;
  --pick:#FFFBF2;
  --line:#EFE7E4;
  --mute:#FAF8F7;
  --ink:#2B2323;
  --sub:#7A706F;
  font-family:-apple-system,BlinkMacSystemFont,"Hiragino Sans","Noto Sans JP",sans-serif;color:var(--ink);margin:1.6em 0;
}
.hcmp *{box-sizing:border-box;}
.hcmp-scroll{overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;border:0;border-radius:14px;box-shadow:0 0 0 1px #E6D9D6,0 12px 28px rgba(94,23,26,.14);background:#fff;padding:0;}
.hcmp-table{width:100%;min-width:716px;border-collapse:separate;border-spacing:0;table-layout:fixed;font-size:13px;line-height:1.5;background:#fff;border-radius:14px;overflow:hidden;margin:0;}
.hcmp-table col.c-label{width:104px;}
.hcmp-table col.c-pick{width:264px;}
.hcmp-table col.c-cl{width:172px;}
.hcmp-table th,.hcmp-table td{padding:12px 10px;text-align:center;vertical-align:middle;border:0;border-bottom:1px solid var(--line);word-break:break-word;background-clip:padding-box;overflow:hidden;}
.hcmp-table tbody tr:last-child th,.hcmp-table tbody tr:last-child td{border-bottom:none;}
.hcmp-table tbody td{background:#fff;}
.hcmp-table tbody tr:nth-child(even) td{background:var(--mute);}
.hcmp .hcmp-table th.corner{position:sticky;left:0;z-index:20 !important;}
.hcmp .hcmp-table th.corner-top{position:sticky;left:0;z-index:20 !important;}
.hcmp .hcmp-table .rowh{position:sticky;left:0;z-index:15;}

/* ---- おすすめポイント行（ダークボルドーの帯） ---- */
.hcmp .hcmp-table .hcmp-catch th{background:var(--deep) !important;color:var(--gold-lt) !important;font-size:12px;font-weight:800;line-height:1.4;padding:10px 6px;border-bottom:0;letter-spacing:.03em;}
.hcmp .hcmp-table .hcmp-catch th::after{content:none;}
.hcmp .hcmp-table th.corner-top{background:var(--deeper) !important;color:#fff !important;border-radius:14px 0 0 0;font-size:11.5px;padding-left:3px;padding-right:3px;letter-spacing:0;}
.hcmp .hcmp-table .hcmp-catch th.pick{background:linear-gradient(135deg,#EBCB72 0%,var(--gold) 55%,#B88A33 100%) !important;color:var(--deep) !important;}
.hcmp .catch-em{display:flex;flex-direction:column;align-items:center;gap:3px;}
.hcmp .catch-txt{display:block;background:transparent;color:var(--deep);font-size:10.5px;font-weight:800;padding:0;line-height:1.35;box-shadow:none;}
.hcmp .catch-em .hl-yel{display:inline-block;color:#fff;background:var(--deep);font-size:16px;font-weight:900;letter-spacing:.18em;padding:3px 14px 3px 18px;border-radius:4px;text-shadow:none;}

/* ---- クリニック行 ---- */
.hcmp .hcmp-table .hcmp-clinic th{background:#fff !important;color:var(--ink) !important;padding:14px 8px 12px;border-bottom:1px solid var(--line);}
.hcmp .hcmp-table th.corner{background:var(--main) !important;color:#fff !important;font-weight:800;border-radius:0;font-size:12.5px;}
.hcmp-clinic a{display:block;}
.hcmp-clinic img{width:100%;max-width:150px;height:auto;border-radius:6px;border:1px solid #E7E0DE;}
.hcmp-clinic th:not(.pick) img{max-width:122px;}
.hcmp-clinic .cname{display:inline-block;font-weight:800;color:#5B5453 !important;background:transparent;border-radius:0;padding:0;margin:8px 0 0;font-size:12px;}
.hcmp-clinic th:not(.pick) .cname{background:transparent !important;color:#5B5453 !important;font-size:12px;}
.hcmp-clinic th.pick .cname{color:#fff !important;background:var(--main);border:1.5px solid var(--gold);border-radius:4px;padding:4px 14px;font-size:14px;letter-spacing:.04em;}

/* ---- 行見出し（ボルドーの縦帯） ---- */
.hcmp .hcmp-table .rowh{background:var(--main) !important;color:#fff !important;font-weight:800;line-height:1.3;word-break:normal;overflow-wrap:break-word;border-bottom:1px solid rgba(255,255,255,.14);}
.hcmp .hcmp-table tr:nth-child(even) .rowh{background:var(--deep) !important;}
.hcmp .hcmp-table .rowh .rlabel{display:inline-block;font-size:12.5px;background:transparent;color:#fff;border:0;border-radius:0;padding:0;line-height:1.3;box-shadow:none;letter-spacing:.06em;}

/* ---- おすすめ列（ゴールド枠のスポットライト） ---- */
.hcmp .hcmp-table td.pick,.hcmp .hcmp-table tr:nth-child(even) td.pick{background:var(--pick) !important;}
.hcmp .hcmp-table .hcmp-clinic th.pick{background:linear-gradient(180deg,#FFF6E0,#fff) !important;position:relative;}
.hcmp .hcmp-table th.pick,.hcmp .hcmp-table td.pick{border-left:2px solid var(--gold);border-right:2px solid var(--gold);}
.hcmp .hcmp-table td.pick-bot{border-bottom:2px solid var(--gold) !important;border-radius:0;overflow:visible !important;}
.hcmp-clinic th.pick img{max-width:196px;border:2px solid var(--gold);}

.hcmp .pick-badge{
  display:inline-flex;align-items:center;justify-content:center;position:absolute;
  top:6px;right:6px;width:56px;height:56px;border-radius:50%;
  background:var(--main);border:2px solid var(--gold);color:var(--gold-lt);
  font-size:11.5px;font-weight:900;line-height:1.2;text-align:center;text-shadow:none;
  box-shadow:0 0 0 3px #fff,0 4px 10px rgba(94,23,26,.3);
  transform:rotate(-8deg);animation:hcmp-badgewobble 2.4s ease-in-out infinite;z-index:5;white-space:nowrap;
}
@keyframes hcmp-badgewobble{0%,100%{transform:rotate(-8deg) scale(1)}50%{transform:rotate(-8deg) scale(1.08)}}

/* ---- ◎○△ アイコン（フラット） ---- */
.hcmp .ic{display:flex;align-items:center;justify-content:center;width:36px;height:36px;margin:0 auto 6px;font-size:20px;font-weight:900;border-radius:50%;line-height:1;position:relative;border:2px solid transparent;box-shadow:none;filter:none;opacity:1;}
.hcmp td.pick .ic{width:46px;height:46px;font-size:26px;}
.hcmp .ic-w{color:#A0686A;background:#F6ECEB;border-color:#E6CFCD;}
.hcmp .ic-b{color:#6A7480;background:#EEF1F4;border-color:#DCE1E6;}
.hcmp .ic-g{color:#9A958E;background:#F3F2F0;border-color:#E3E1DD;}
.hcmp td.pick .ic-w{color:var(--gold-lt);background:var(--main);border-color:var(--gold);box-shadow:0 3px 8px rgba(142,41,44,.25);}
.hcmp td.pick .ic-w::before{content:"✦";position:absolute;top:-7px;right:-7px;font-size:12px;color:var(--gold);animation:hcmp-sparkle 1.6s ease-in-out infinite;}
@keyframes hcmp-sparkle{0%,100%{opacity:.3;transform:scale(.8)}50%{opacity:1;transform:scale(1.15)}}
.hcmp td:not(.pick) .price.gp b,.hcmp td:not(.pick) .price.gp em{color:#5B5453;}
.hcmp td:not(.pick) .hl{color:#5B5453;}
.hcmp td:not(.pick) b{color:#4A4342;}
.hcmp .note{display:block;color:var(--sub);font-size:11px;margin:2px 0;text-align:center;}
.hcmp .acc-n{display:block;margin:0 0 6px;font-size:14px;}

/* ---- 価格 ---- */
.hcmp .price{display:inline-block;max-width:100%;font-weight:800;margin:3px auto;color:var(--main);line-height:1.1;background:transparent;border-radius:0;padding:0 4px;position:relative;}
.hcmp .price b{font-size:18px;letter-spacing:.01em;}
.hcmp td.pick .price{background:linear-gradient(transparent 62%,var(--gold-hl) 62%);border:0;box-shadow:none;animation:none;padding:0 6px;}
.hcmp td.pick .price b{font-size:32px;}
.hcmp .price em{font-size:12px;font-style:normal;font-weight:700;}

.hcmp .hl{color:var(--main);font-weight:900;}
.hcmp .mark{background:linear-gradient(transparent 60%,var(--gold-hl) 60%);padding:0 3px;font-weight:800;border-radius:0;color:var(--main);}

/* ---- 医療ローン ---- */
.hcmp .loan-ok{display:inline-block;color:var(--main);font-weight:900;font-size:13.5px;background:linear-gradient(transparent 60%,var(--gold-hl) 60%);padding:0 4px;margin-bottom:3px;}
.hcmp .loan-box{background:#fff;border:1px dashed var(--gold);border-radius:6px;padding:6px;margin:6px auto 4px;box-shadow:none;text-align:center;max-width:220px;}
.hcmp .loan-plan{font-size:9px;color:var(--sub);font-weight:700;margin-bottom:2px;}
.hcmp .loan-price-wrap{display:flex;align-items:center;justify-content:center;gap:5px;}
.hcmp .loan-base{white-space:nowrap;font-size:14px;font-weight:800;color:#6E6665;line-height:1;}
.hcmp .loan-base small{font-size:9px;}
.hcmp .loan-arrow{color:var(--gold);font-size:12px;font-weight:900;background:transparent;border-radius:0;width:auto;height:auto;display:inline-flex;}
.hcmp .loan-monthly{white-space:nowrap;font-size:11px;font-weight:800;color:var(--main);line-height:1;}
.hcmp .loan-monthly .loan-hl{font-size:21px;background:none;padding:0 1px;margin-left:1px;}
.hcmp .loan-monthly .loan-hl small{font-size:10px;font-weight:800;}

/* ---- マイクロコピー ---- */
.hcmp .m-copy{
  display:inline-block;line-height:1.35;margin:12px auto 10px;white-space:nowrap;
  background:var(--deep);color:var(--gold-lt);font-size:12.5px;font-weight:800;
  border-radius:999px;padding:6px 16px;border:0;box-shadow:none;position:relative;text-shadow:none;letter-spacing:.03em;
  animation:none;
}
.hcmp .m-copy::before{content:"";position:absolute;bottom:-6px;left:50%;transform:translateX(-50%);border-left:6px solid transparent;border-right:6px solid transparent;border-top:7px solid var(--deep);}
.hcmp .m-copy::after{content:none;}

/* キャンペーン期限バッジ */
.hcmp .m-badge{
  display:inline-flex;align-items:center;justify-content:center;position:absolute;
  top:-20px;right:-22px;width:52px;height:52px;border-radius:50%;
  background:var(--main);border:2px solid var(--gold);color:var(--gold-lt);font-size:11px;font-weight:900;line-height:1.15;text-align:center;
  text-shadow:none;transform:rotate(12deg);animation:hcmp-m-badgewobble 2.5s ease-in-out infinite;z-index:20;
  box-shadow:0 0 0 2px #fff,0 4px 8px rgba(0,0,0,.2);
}
@keyframes hcmp-m-badgewobble{0%,100%{transform:rotate(12deg) scale(1);}50%{transform:rotate(12deg) scale(1.08);}}

/* ---- ボタン ---- */
.hcmp .btn{position:relative;display:inline-block;overflow:hidden;text-decoration:none !important;font-weight:800;font-size:12px;border-radius:8px;padding:11px 10px;line-height:1.3;width:100%;max-width:190px;color:#fff;transition:.15s;box-shadow:none;cursor:pointer;}
.hcmp .btn:hover{transform:translateY(1px);}
.hcmp .btn+.btn{margin-top:7px;}
.hcmp td.pick .btn{max-width:214px;}

.hcmp .btn-red{background:#fff;color:#5B5453 !important;border:1.5px solid #CFC5C3;box-shadow:0 3px 0 #E4DCDA;}
.hcmp .btn-red::after{content:"›";margin-left:6px;font-weight:900;}
.hcmp .btn-red:hover{box-shadow:0 2px 0 #E4DCDA;}
.hcmp .btn-cv{background:linear-gradient(180deg,var(--cta1),var(--cta2));color:var(--deeper) !important;font-size:14px;padding:13px 10px;border-radius:10px;box-shadow:0 4px 0 var(--cta-sh),0 8px 16px rgba(227,162,26,.35);animation:hcmp-cvbounce 2s ease-in-out infinite;}
.hcmp .btn-cv::before{content:"";position:absolute;top:0;left:-60%;width:40%;height:100%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.6),transparent);transform:skewX(-20deg);animation:hcmp-shine 3s ease-in-out infinite;}
.hcmp .btn-cv::after{content:"▶";position:absolute;right:12px;top:50%;transform:translateY(-50%);font-size:9px;}
@keyframes hcmp-shine{0%,60%{left:-60%}100%{left:130%}}
@keyframes hcmp-cvbounce{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}

.hcmp .btn-detail,.hcmp .btn-acc{background:transparent;color:var(--main) !important;border:1px solid #E2D2CF;box-shadow:none;font-size:10.5px;font-weight:700;padding:6px 8px;border-radius:999px;max-width:156px;white-space:nowrap;}
.hcmp td.pick .btn-detail,.hcmp td.pick .btn-acc{max-width:160px;background:#fff;}
.hcmp .btn-detail:hover,.hcmp .btn-acc:hover{background:var(--main);color:#fff !important;border-color:var(--main);transform:none;}
.hcmp .btn-detail::after{content:"›";margin-left:4px;font-weight:900;}
.hcmp .btn-acc::after{content:"＋";margin-left:4px;}

/* ---- モーダル ---- */
.hcmp .hcmp-mtoggle{position:absolute;width:0;height:0;opacity:0;pointer-events:none;}
.hcmp .hcmp-modal{display:none;position:fixed;inset:0;z-index:99999;align-items:center;justify-content:center;padding:16px;}
.hcmp div:has(.hcmp-mtoggle:checked) + .hcmp-modal{display:flex;}
.hcmp .hcmp-modal-bg{position:absolute;inset:0;background:rgba(40,10,12,.6);cursor:pointer;}
.hcmp .hcmp-modal-box{position:relative;z-index:1;width:100%;max-width:460px;max-height:82vh;background:#fff;border-radius:14px;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.35);border:0;}
.hcmp .hcmp-modal-head{background:var(--deep);color:#fff;font-weight:800;padding:14px 18px;font-size:14.5px;border-bottom:3px solid var(--gold);}
.hcmp .hcmp-modal-body{padding:8px 18px;overflow:auto;-webkit-overflow-scrolling:touch;}
.hcmp .hcmp-acc-item{text-align:left;padding:11px 4px 11px 12px;border-bottom:1px solid var(--line);border-left:3px solid var(--gold);margin:6px 0;font-size:13px;line-height:1.6;color:var(--ink);}
.hcmp .hcmp-acc-item:last-child{border-bottom:none;}
.hcmp .hcmp-acc-item b{display:block;color:var(--main);font-size:13.5px;margin-bottom:2px;}
.hcmp .hcmp-modal-foot{padding:12px;text-align:center;border-top:1px solid var(--line);background:var(--mute);}
.hcmp .hcmp-close{display:inline-block;cursor:pointer;background:var(--main);color:#fff;font-weight:700;border-radius:999px;padding:10px 26px;font-size:13px;}
.hcmp .hcmp-close:hover{opacity:.88;}

/* ---- スマホ：縦1画面に収まるコンパクト表示（横スクロールは維持） ---- */
