  .hcmp{margin:1.2em 0;}
  .hcmp-scroll{border-radius:10px;}
  .hcmp-table{font-size:9.5px;line-height:1.2;width:676px;min-width:676px;border-radius:10px;}
  .hcmp-table th,.hcmp-table td{padding:3px 3px;}
  .hcmp-table td{position:relative;padding-left:21px;}
  .hcmp-table td br{display:none;}            /* 改行を詰めて行数を削減 */
  .hcmp-table col.c-label{width:36px;}
  .hcmp-table col.c-pick{width:190px;}
  .hcmp-table col.c-cl{width:225px;}

  .hcmp .hcmp-table .hcmp-catch th{font-size:9px;padding:3px 2px;line-height:1.15;letter-spacing:0;}
  .hcmp .hcmp-table th.corner-top{font-size:8px;}
  .hcmp .catch-em{gap:1px;}
  .hcmp .catch-txt{font-size:8px;line-height:1.15;}
  .hcmp .catch-em .hl-yel{font-size:11px;letter-spacing:.1em;padding:1px 8px 1px 9px;border-radius:3px;}

  .hcmp .hcmp-table .rowh .rlabel{font-size:8.5px;letter-spacing:-0.03em;line-height:1.15;}
  .hcmp .hcmp-table th.corner{font-size:8.5px;}
  .hcmp .hcmp-table .hcmp-clinic th{padding:4px 2px 3px !important;}
  .hcmp-clinic img{width:auto;max-width:70px;max-height:40px;object-fit:contain;border-radius:4px;margin:0 auto;}
  .hcmp-clinic th.pick img{max-width:96px;max-height:48px;border-width:1.5px;}
  .hcmp-clinic .cname,.hcmp-clinic th:not(.pick) .cname{font-size:9px;margin:2px 0 0;}
  .hcmp-clinic th.pick .cname{font-size:9.5px;padding:1px 6px;border-width:1px;border-radius:3px;}
  .hcmp .pick-badge{width:34px;height:34px;font-size:7px;top:2px;right:2px;letter-spacing:-0.05em;border-width:1.5px;box-shadow:0 0 0 2px #fff,0 2px 4px rgba(94,23,26,.3);}

  /* ◎○△はセル左上に配置して縦幅を節約 */
  .hcmp .ic,.hcmp td.pick .ic{position:absolute;top:3px;left:3px;width:15px;height:15px;font-size:9px;margin:0;border-width:1px;}
  .hcmp td.pick .ic{width:17px;height:17px;font-size:10.5px;}
  .hcmp td.pick .ic-w::before{font-size:7px;top:-4px;right:-5px;}
  .hcmp .acc-n{display:inline-block;font-size:10px;margin:0 4px 0 0;vertical-align:middle;}
  .hcmp .price{padding:0 3px;margin:0 auto;}
  .hcmp .price b{font-size:12px;}
  .hcmp td.pick .price b{font-size:16px;}
  .hcmp .price em{font-size:8px;}
  .hcmp .note{font-size:7.5px;line-height:1.2;margin:1px 0 0;}

  .hcmp .loan-ok{font-size:9.5px;padding:0 2px;margin:0;}
  .hcmp .loan-box{padding:1px 4px;margin:1px auto;max-width:150px;border-radius:4px;}
  .hcmp .loan-plan{font-size:7px;margin:0;white-space:nowrap;}
  .hcmp .loan-price-wrap{gap:3px;}
  .hcmp .loan-base{white-space:nowrap;font-size:9px;}
  .hcmp .loan-base small{font-size:6.5px;}
  .hcmp .loan-arrow{font-size:7px;}
  .hcmp .loan-monthly{white-space:nowrap;font-size:7.5px;}
  .hcmp .loan-monthly .loan-hl{font-size:12px;}
  .hcmp .loan-monthly .loan-hl small{font-size:7px;}

  .hcmp .m-copy{font-size:8px;padding:2px 8px;margin:1px auto 4px;}
  .hcmp .m-copy::before{bottom:-4px;border-left-width:4px;border-right-width:4px;border-top-width:5px;}

  .hcmp .m-badge{width:40px;height:40px;font-size:8px;top:-16px;right:-16px;border-width:1.5px;}

  .hcmp .btn{font-size:8.5px;padding:4px 2px;border-radius:5px;}
  .hcmp .btn-cv{font-size:9.5px;padding:5px 2px;border-radius:6px;box-shadow:0 2px 0 var(--cta-sh);animation:none;}
  .hcmp .btn-cv::after{content:none;}
  .hcmp .btn-red{box-shadow:0 2px 0 #E4DCDA;}
  .hcmp .btn-detail,.hcmp .btn-acc,.hcmp td.pick .btn-detail,.hcmp td.pick .btn-acc{display:inline-block;width:auto;font-size:8px;padding:2px 8px;max-width:100%;vertical-align:middle;}
  .hcmp .btn+.btn{margin-top:3px;}
}

/* =========================================================
   包茎治療クリニック診断（.pdx-box）クラシックエディタ対応版
   ※JavaScript不使用（ラジオボタン＋CSSの:hasで動作）
   ========================================================= */
.pdx-box {
	--pdx-main: var(--color_main, #1f6fb5);
	--pdx-accent: #ef4132;
	--pdx-cta: #ff8a00;
	--pdx-text: #333;
	--pdx-bg: #f4f8fc;
	position: relative;
	display: block;
	max-width: 860px;
	margin: 40px auto 50px !important;
	padding: 0 !important;
	background: var(--pdx-bg);
	border: 3px solid var(--pdx-main);
	border-radius: 16px;
	overflow: hidden;
	color: var(--pdx-text);
	line-height: 1.6;
	box-sizing: border-box;
}
.pdx-box *, .pdx-box *::before, .pdx-box *::after { box-sizing: border-box; }
.pdx-box p { margin: 0 !important; }
.pdx-box br { display: none; } /* 自動挿入された改行タグ対策 */
.pdx-box .pdx-inputs { position: absolute; width: 1px; height: 1px; overflow: hidden; margin: 0 !important; padding: 0 !important; }
.pdx-box .pdx-radio { position: absolute; opacity: 0; width: 1px; height: 1px; margin: 0; pointer-events: none; }

/* ヘッダー */
.pdx-head { background: var(--pdx-main); color: #fff; text-align: center; padding: 22px 16px 20px; }
.pdx-head__sub {
	display: inline-block; background: #fff; color: var(--pdx-main);
	font-size: 14px; font-weight: bold; padding: 3px 14px; border-radius: 30px;
	margin-bottom: 10px !important;
}
.pdx-head__title { font-size: clamp(20px, 5vw, 30px); font-weight: bold; line-height: 1.35; color: #fff; }
.pdx-head__title span { display: inline-block; }

/* ステップ */
.pdx-box .pdx-steps {
	display: flex; justify-content: center; gap: 6px;
	list-style: none !important; margin: 20px auto 0 !important; padding: 0 12px !important;
	border: 0 !important; background: none !important;
}
.pdx-box .pdx-steps li {
	flex: 1 1 0; max-width: 110px; margin: 0 !important; padding: 6px 0 !important;
	list-style: none !important; text-align: center; font-size: 13px; font-weight: bold;
	color: #999; background: #fff; border: 1px solid #d5dde6; border-radius: 6px; transition: all .3s;
}
.pdx-box .pdx-steps li::before, .pdx-box .pdx-steps li::after { display: none !important; content: none !important; }
/* 完了済みステップ */
.pdx-box:has(#pdx-q1n:not(:checked)) .pdx-steps li:nth-child(1),
.pdx-box:has(#pdx-q2n:not(:checked)) .pdx-steps li:nth-child(2),
.pdx-box:has(#pdx-q3n:not(:checked)) .pdx-steps li:nth-child(3),
.pdx-box:has(#pdx-q4n:not(:checked)) .pdx-steps li:nth-child(4) { background: #dbe8f5; color: var(--pdx-main); border-color: #dbe8f5; }
/* 現在のステップ */
.pdx-box:has(#pdx-q1n:checked) .pdx-steps li:nth-child(1),
.pdx-box:has(#pdx-q1n:not(:checked)):has(#pdx-q2n:checked) .pdx-steps li:nth-child(2),
.pdx-box:has(#pdx-q2n:not(:checked)):has(#pdx-q3n:checked) .pdx-steps li:nth-child(3),
.pdx-box:has(#pdx-q3n:not(:checked)):has(#pdx-q4n:checked) .pdx-steps li:nth-child(4),
.pdx-box:has(#pdx-q4n:not(:checked)) .pdx-steps li:nth-child(5) { background: var(--pdx-main); color: #fff; border-color: var(--pdx-main); }

.pdx-body { padding: 20px 4% 28px; }

/* 設問：回答状況に応じて1問ずつ表示 */
.pdx-q, .pdx-result { display: none; }
.pdx-box:has(#pdx-q1n:checked) .pdx-q1,
.pdx-box:has(#pdx-q1n:not(:checked)):has(#pdx-q2n:checked) .pdx-q2,
.pdx-box:has(#pdx-q2n:not(:checked)):has(#pdx-q3n:checked) .pdx-q3,
.pdx-box:has(#pdx-q3n:not(:checked)):has(#pdx-q4n:checked) .pdx-q4 { display: block; animation: pdxFade .35s ease; }
.pdx-box:has(#pdx-q4n:not(:checked)) .pdx-result { display: block; animation: pdxFade .45s ease; }
.pdx-nav { display: block; margin-top: 16px; text-align: center; }

.pdx-q-title {
	display: flex; align-items: center; gap: 12px; background: #fff; border-radius: 12px;
	padding: 14px 16px; margin-bottom: 18px !important;
	font-size: clamp(16px, 4.2vw, 21px); font-weight: bold; line-height: 1.4;
	box-shadow: 0 2px 6px rgba(0,0,0,.06);
}
.pdx-q-title .pdx-q-num {
	flex-shrink: 0; display: flex; align-items: center; justify-content: center;
	width: 44px; height: 44px; border-radius: 50%;
	background: var(--pdx-main); color: #fff; font-size: 17px;
}
.pdx-options { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }
.pdx-options.is-col1 { grid-template-columns: 1fr; }
.pdx-box .pdx-opt {
	display: flex; flex-direction: column; align-items: center; justify-content: center;
	width: 100%; min-height: 58px; margin: 0; padding: 10px 14px;
	background: #fff; color: var(--pdx-accent); border: 2px solid var(--pdx-accent); border-radius: 40px;
	font-size: clamp(15px, 3.8vw, 18px); font-weight: bold; line-height: 1.35; text-align: center;
	cursor: pointer; transition: background .2s, color .2s, transform .1s;
	-webkit-user-select: none; user-select: none;
}
.pdx-opt small { display: block; font-size: 75%; font-weight: normal; }
.pdx-box .pdx-opt:hover { background: var(--pdx-accent); color: #fff; }
.pdx-opt:active { transform: scale(.98); }
.pdx-box .pdx-back {
	display: inline-block; background: none; border: 0; color: #777; font-size: 14px;
	text-decoration: underline; cursor: pointer; padding: 4px;
}

/* ===== 結果（スマホ1画面に収まるコンパクト表示） ===== */
.pdx-box:has(#pdx-q4n:not(:checked)) .pdx-body { padding: 18px 12px 12px; }
.pdx-res { display: none; }
.pdx-res-mens { display: var(--pdx-show-mens, block); }
.pdx-res-abc  { display: var(--pdx-show-abc, none); }
.pdx-res-ueno { display: var(--pdx-show-ueno, none); }
.pdx-card {
	position: relative; background: #fff; border: 3px solid var(--pdx-cta); border-radius: 12px;
	padding: 18px 12px 12px; box-shadow: 0 3px 10px rgba(0,0,0,.07);
}
.pdx-card__badge {
	position: absolute; top: -12px; left: 50%; transform: translateX(-50%);
	background: var(--pdx-cta); color: #fff; font-weight: bold; font-size: 12px; line-height: 1.6;
	padding: 2px 16px; border-radius: 30px; white-space: nowrap;
}
.pdx-card__top { display: flex; align-items: center; gap: 10px; }
.pdx-box .pdx-card__img { flex: 0 0 auto; }
.pdx-box .pdx-banner { width: 88px; display: block; text-decoration: none !important; }
.pdx-box .pdx-banner img {
	display: block; width: 88px !important; height: 88px !important; max-width: none;
	object-fit: contain; border-radius: 6px; margin: 0 !important;
}
.pdx-card__info { flex: 1 1 auto; min-width: 0; }
.pdx-card__name { font-size: 18px; font-weight: bold; color: var(--pdx-main); line-height: 1.3; }
.pdx-card__catch { font-size: 12px; color: #666; line-height: 1.45; margin-top: 4px !important; }

.pdx-reasons { background: #fff8ef; border-radius: 8px; padding: 7px 10px; margin: 10px 0 0; }
.pdx-reasons__ttl { font-weight: bold; font-size: 12px; line-height: 1.5; }
.pdx-box .pdx-reasons ul { margin: 2px 0 0 !important; padding: 0 !important; border: 0 !important; background: none !important; }
.pdx-box .pdx-reasons li {
	position: relative; list-style: none !important; margin: 0 !important;
	padding: 0 0 0 1.3em !important; font-size: 12.5px; line-height: 1.55; border: 0 !important;
}
.pdx-box .pdx-reasons li.pdx-rs { display: none; }
.pdx-box .pdx-reasons li::before {
	content: "✓" !important; position: absolute; left: 0; top: 0;
	color: var(--pdx-cta); font-weight: bold; border: 0; background: none; width: auto; height: auto;
	display: block !important; transform: none;
}
.pdx-box .pdx-btn {
	display: block; text-align: center; padding: 9px 8px 8px; margin-top: 10px; border-radius: 50px;
	background: var(--pdx-cta); color: #fff !important; box-shadow: 0 3px 0 #c96a00;
	font-weight: bold; font-size: 15px; text-decoration: none !important; line-height: 1.3;
	transition: opacity .2s, transform .1s;
}
.pdx-box .pdx-btn:hover { opacity: .85; }
.pdx-box .pdx-btn:active { transform: translateY(2px); box-shadow: 0 1px 0 #c96a00; }
.pdx-btn span, .pdx-btn small { display: block; }
.pdx-btn small { font-size: 11px; font-weight: normal; }

.pdx-others { margin-top: 10px; }
.pdx-others__ttl { font-weight: bold; text-align: center; font-size: 12px; line-height: 1.5; margin-bottom: 4px !important; }
.pdx-box .pdx-others__list { display: flex !important; flex-direction: row !important; gap: 6px; }
.pdx-box .pdx-mini {
	flex: 1 1 50%; min-width: 0; display: flex; align-items: center; gap: 6px;
	background: #fff; border: 1px solid #d5dde6; border-radius: 8px; padding: 5px 6px;
	text-decoration: none !important; color: var(--pdx-main) !important; text-align: left;
}
.pdx-mini__banner { flex: 0 0 36px; display: block; }
.pdx-box .pdx-mini__banner img {
	display: block; width: 36px !important; height: 36px !important; max-width: none;
	object-fit: cover; border-radius: 4px; margin: 0 !important;
}
.pdx-mini__name { display: block; font-size: 11.5px; font-weight: bold; line-height: 1.3; }

.pdx-result__foot { display: flex; align-items: flex-start; gap: 6px; margin-top: 8px; }
.pdx-answers { flex: 1 1 auto; font-size: 12px; color: #666; background: #fff; border-radius: 8px; padding: 5px 10px; }
.pdx-answers summary { cursor: pointer; font-weight: bold; line-height: 1.6; }
.pdx-box .pdx-answers dl { margin: 4px 0 0 !important; }
.pdx-box .pdx-answers dt { font-weight: bold; margin-top: 2px; }
.pdx-box .pdx-answers dd { margin: 0 0 0 1em !important; }
.pdx-box .pdx-answers dd.pdx-ans { display: none; }
.pdx-restart-wrap { flex: 0 0 auto; }
.pdx-box .pdx-restart {
	margin: 0; background: var(--pdx-main); color: #fff; border: 0;
	border-radius: 40px; padding: 5px 14px; font-size: 12px; line-height: 1.6; font-weight: bold; cursor: pointer; font-family: inherit;
}
.pdx-note { font-size: 9.5px; color: #888; line-height: 1.45; margin-top: 6px !important; }

@keyframes pdxFade { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

@media (min-width: 601px) {
	.pdx-box .pdx-banner { width: 130px; }
	.pdx-box .pdx-banner img { width: 130px !important; height: 130px !important; }
	.pdx-card__name { font-size: 22px; }
	.pdx-card__catch, .pdx-box .pdx-reasons li { font-size: 14px; }
	.pdx-mini__name { font-size: 13px; }
}
@media (max-width: 600px) {
	.pdx-options { grid-template-columns: 1fr; }
	.pdx-box .pdx-steps li { font-size: 11px; }
	.pdx-q-title .pdx-q-num { width: 38px; height: 38px; font-size: 15px; }
	/* 結果表示中はヘッダーを縮め、ステップを省略して1画面に収める */
	.pdx-box:has(#pdx-q4n:not(:checked)) .pdx-head__sub { display: none; }
	.pdx-box:has(#pdx-q4n:not(:checked)) .pdx-head { padding: 8px 10px; }
	.pdx-box:has(#pdx-q4n:not(:checked)) .pdx-head__title { font-size: 15px; }
	.pdx-box:has(#pdx-q4n:not(:checked)) .pdx-steps { display: none; }
}

/* --- 回答に応じた表示切替（自動生成：編集不要） --- */
.pdx-box:has(#pdx-q1a:checked) :is(.pdx-rs-q1a,.pdx-ans-q1a),
.pdx-box:has(#pdx-q1b:checked) :is(.pdx-rs-q1b,.pdx-ans-q1b),
.pdx-box:has(#pdx-q1c:checked) :is(.pdx-rs-q1c,.pdx-ans-q1c),
.pdx-box:has(#pdx-q1d:checked) :is(.pdx-rs-q1d,.pdx-ans-q1d),
.pdx-box:has(#pdx-q2a:checked) :is(.pdx-rs-q2a,.pdx-ans-q2a),
.pdx-box:has(#pdx-q2b:checked) :is(.pdx-rs-q2b,.pdx-ans-q2b),
.pdx-box:has(#pdx-q2c:checked) :is(.pdx-rs-q2c,.pdx-ans-q2c),
.pdx-box:has(#pdx-q2d:checked) :is(.pdx-rs-q2d,.pdx-ans-q2d),
.pdx-box:has(#pdx-q3a:checked) :is(.pdx-rs-q3a,.pdx-ans-q3a),
.pdx-box:has(#pdx-q3b:checked) :is(.pdx-rs-q3b,.pdx-ans-q3b),
.pdx-box:has(#pdx-q3c:checked) :is(.pdx-rs-q3c,.pdx-ans-q3c),
.pdx-box:has(#pdx-q4a:checked) :is(.pdx-rs-q4a,.pdx-ans-q4a),
.pdx-box:has(#pdx-q4b:checked) :is(.pdx-rs-q4b,.pdx-ans-q4b),
.pdx-box:has(#pdx-q4c:checked) :is(.pdx-rs-q4c,.pdx-ans-q4c),
.pdx-box:has(#pdx-q4d:checked) :is(.pdx-rs-q4d,.pdx-ans-q4d),
.pdx-box:has(#pdx-q4e:checked) :is(.pdx-rs-q4e,.pdx-ans-q4e),
.pdx-box:has(#pdx-q4f:checked) :is(.pdx-rs-q4f,.pdx-ans-q4f){display:block;}
.pdx-box:has(#pdx-q3c:checked):has(#pdx-q4f:checked) .pdx-res-ueno .pdx-rs-q4f{display:none;}
.pdx-box:has(#pdx-q1a:checked):has(#pdx-q2a:checked):has(#pdx-q3a:checked):has(:is(#pdx-q4a,#pdx-q4b,#pdx-q4c,#pdx-q4d,#pdx-q4e):checked),
.pdx-box:has(#pdx-q1a:checked):has(#pdx-q2a:checked):has(#pdx-q3b:checked):has(:is(#pdx-q4a,#pdx-q4b,#pdx-q4c,#pdx-q4d,#pdx-q4e):checked),
.pdx-box:has(#pdx-q1a:checked):has(#pdx-q2a:checked):has(#pdx-q3c:checked):has(:is(#pdx-q4a,#pdx-q4b,#pdx-q4c):checked),
.pdx-box:has(#pdx-q1a:checked):has(#pdx-q2b:checked):has(#pdx-q3a:checked):has(:is(#pdx-q4a,#pdx-q4b,#pdx-q4c,#pdx-q4d):checked),
.pdx-box:has(#pdx-q1a:checked):has(#pdx-q2b:checked):has(#pdx-q3b:checked):has(:is(#pdx-q4a,#pdx-q4b,#pdx-q4c,#pdx-q4d):checked),
.pdx-box:has(#pdx-q1a:checked):has(#pdx-q2b:checked):has(#pdx-q3c:checked):has(:is(#pdx-q4a,#pdx-q4b):checked),
.pdx-box:has(#pdx-q1a:checked):has(#pdx-q2c:checked):has(#pdx-q3a:checked):has(:is(#pdx-q4a,#pdx-q4b,#pdx-q4c,#pdx-q4d,#pdx-q4e):checked),
